functions.mtd_get_master:
static inline struct mtd_info *mtd_get_master(struct mtd_info *mtd)
{
	while (mtd->parent)
		mtd = mtd->parent;

	return mtd;
}

functions.mtd_sync:
static inline void mtd_sync(struct mtd_info *mtd)
{
	struct mtd_info *master = mtd_get_master(mtd);

	if (master->_sync)
		master->_sync(master);
}

functions.__mtd_next_device:
struct mtd_info *__mtd_next_device(int i)
{
	struct mtd_info *mtd;

	while ((mtd = idr_get_next(&mtd_idr, &i))) {
		if (mtd->registered)
			return mtd;
		i++;
	}

	return NULL;
}

functions.mtd_master_release:
static void mtd_master_release(struct kref *ref)
{
	struct mtd_info *master = container_of(ref, struct mtd_info,
					     master.life_refcnt);
	struct completion *done = master->master.release_done;
	struct module *owner = master->master.release_owner;

	master->master.release(master);
	if (done)
		complete(done);
	else
		module_put(owner);
}

functions.mtd_put_lifetime:
void mtd_put_lifetime(struct mtd_info *master)
{
	if (master->master.release)
		kref_put(&master->master.life_refcnt, mtd_master_release);
}

functions.mtd_set_release:
void mtd_set_release(struct mtd_info *master,
		     void (*release)(struct mtd_info *mtd))
{
	kref_init(&master->master.life_refcnt);
	master->master.release = release;
}

functions.mtd_put_master:
void mtd_put_master(struct mtd_info *master)
{
	DECLARE_COMPLETION_ONSTACK(done);

	if ((!master->owner || READ_ONCE(master->owner->state) == MODULE_STATE_LIVE) &&
	    try_module_get(master->owner)) {
		master->master.release_owner = master->owner;
		mtd_put_lifetime(master);
	} else {
		master->master.release_done = &done;
		mtd_put_lifetime(master);
		wait_for_completion(&done);
	}
}

functions.mtd_release:
static void mtd_release(struct device *dev)
{
	struct mtd_info *mtd = dev_get_drvdata(dev);
	struct mtd_info *master = mtd->ref_master;
	struct mtd_info *parent = mtd->parent;

	/* Retained NVMEM providers use the MTD number in their device name. */
	ida_free(&mtd_ids, mtd->index);
	of_node_put(mtd_get_of_node(mtd));

	if (mtd_is_partition(mtd))
		release_mtd_partition(mtd);

	if (master) {
		/* Nested partitions can outlive device_del() of their parents. */
		if (parent && parent != master)
			put_device(&parent->dev);
		mtd_put_lifetime(master);
	}
}

functions.mtd_device_release:
static void mtd_device_release(struct kref *kref)
{
	struct mtd_info *mtd = container_of(kref, struct mtd_info, refcnt);
	bool is_partition = mtd_is_partition(mtd);
	bool managed = mtd->ref_master;

	/* The table mutex is held by the registration or handle put path. */
	idr_remove(&mtd_idr, mtd->index);
	device_destroy(&mtd_class, MTD_DEVT(mtd->index) + 1);

	debugfs_remove_recursive(mtd->dbg.dfs_dir);

	/* Try to remove the NVMEM provider */
	nvmem_unregister(mtd->nvmem);

	device_unregister(&mtd->dev);

	/*
	 *  Clear dev so mtd can be safely re-registered later if desired.
	 *  Should not be done for partition,
	 *  as it was already destroyed in device_unregister().
	 */
	if (!is_partition && !managed)
		memset(&mtd->dev, 0, sizeof(mtd->dev));
}

functions.del_mtd_device:
int del_mtd_device(struct mtd_info *mtd)
{
	int ret;
	struct mtd_notifier *not;

	mutex_lock(&mtd_table_mutex);

	if (idr_find(&mtd_idr, mtd->index) != mtd || !mtd->registered) {
		ret = -ENODEV;
		goto out_error;
	}

	/* No need to get a refcount on the module containing
		the notifier, since we hold the mtd_table_mutex */
	list_for_each_entry(not, &mtd_notifiers, list)
		not->remove(mtd);

	mtd->registered = false;
	kref_put(&mtd->refcnt, mtd_device_release);
	ret = 0;

out_error:
	mutex_unlock(&mtd_table_mutex);
	return ret;
}

functions.get_mtd_device:
struct mtd_info *get_mtd_device(struct mtd_info *mtd, int num)
{
	struct mtd_info *ret = NULL, *other;
	int err = -ENODEV;

	mutex_lock(&mtd_table_mutex);

	if (num == -1) {
		mtd_for_each_device(other) {
			if (other == mtd) {
				ret = mtd;
				break;
			}
		}
	} else if (num >= 0) {
		ret = idr_find(&mtd_idr, num);
		if (mtd && mtd != ret)
			ret = NULL;
	}

	if (!ret) {
		ret = ERR_PTR(err);
		goto out;
	}

	err = __get_mtd_device(ret);
	if (err)
		ret = ERR_PTR(err);
out:
	mutex_unlock(&mtd_table_mutex);
	return ret;
}

functions.__get_mtd_device:
int __get_mtd_device(struct mtd_info *mtd)
{
	struct mtd_info *master = mtd_get_master(mtd);
	bool master_ref = mtd == master || IS_ENABLED(CONFIG_MTD_PARTITIONED_MASTER);
	int err;

	if (!mtd->registered)
		return -ENODEV;

	if (master->_get_device) {
		err = master->_get_device(mtd);
		if (err)
			return err;
	}

	if (!try_module_get(master->owner)) {
		if (master->_put_device)
			master->_put_device(master);
		return -ENODEV;
	}

	mtd_get_lifetime(master);
	while (mtd) {
		if (mtd != master)
			kref_get(&mtd->refcnt);
		mtd = mtd->parent;
	}

	if (master_ref)
		kref_get(&master->refcnt);

	return 0;
}

functions.__put_mtd_device:
void __put_mtd_device(struct mtd_info *mtd)
{
	struct mtd_info *master = mtd_get_master(mtd);
	bool master_ref = mtd == master || IS_ENABLED(CONFIG_MTD_PARTITIONED_MASTER);
	/* master can be freed in _put_device */
	struct module *owner = master->owner;
	bool managed = master->master.release;

	while (mtd) {
		/* kref_put() can relese mtd, so keep a reference mtd->parent */
		struct mtd_info *parent = mtd->parent;

		if (mtd != master)
			kref_put(&mtd->refcnt, mtd_device_release);
		mtd = parent;
	}

	if (master_ref)
		kref_put(&master->refcnt, mtd_device_release);

	/* Legacy _put_device() callbacks can free an unmanaged master. */
	if (master->_put_device)
		master->_put_device(master);
	if (managed)
		mtd_put_lifetime(master);

	/* _put_device() runs code from @owner, so drop the module last */
	module_put(owner);
}

functions.mtd_device_unregister:
int mtd_device_unregister(struct mtd_info *master)
{
	int err;

	mutex_lock(&master->master.partitions_lock);
	master->master.unregistering = true;
	mutex_unlock(&master->master.partitions_lock);

	if (master->_reboot) {
		unregister_reboot_notifier(&master->reboot_notifier);
		memset(&master->reboot_notifier, 0, sizeof(master->reboot_notifier));
	}

	nvmem_unregister(master->otp_user_nvmem);
	nvmem_unregister(master->otp_factory_nvmem);

	if (IS_REACHABLE(CONFIG_MTD_VIRT_CONCAT)) {
		err = mtd_virt_concat_destroy(master);
		if (err)
			return err;
	}
	err = del_mtd_partitions(master);
	if (err)
		return err;

	if (!device_is_registered(&master->dev))
		return 0;

	return del_mtd_device(master);
}

functions.__del_mtd_partitions:
static int __del_mtd_partitions(struct mtd_info *mtd)
{
	struct mtd_info *child, *next;
	int ret, err = 0;

	list_for_each_entry_safe(child, next, &mtd->partitions, part.node) {
		if (mtd_has_partitions(child))
			__del_mtd_partitions(child);

		pr_info("Deleting %s MTD partition\n", child->name);
		list_del_init(&child->part.node);
		ret = del_mtd_device(child);
		if (ret < 0) {
			pr_err("Error when deleting partition \"%s\" (%d)\n",
			       child->name, ret);
			err = ret;
			continue;
		}
	}

	return err;
}

functions.del_mtd_partitions:
int del_mtd_partitions(struct mtd_info *mtd)
{
	struct mtd_info *master = mtd_get_master(mtd);
	int ret;

	pr_info("Deleting MTD partitions on \"%s\":\n", mtd->name);

	mutex_lock(&master->master.partitions_lock);
	if (IS_REACHABLE(CONFIG_MTD_VIRT_CONCAT))
		mtd_virt_concat_destroy(mtd);
	ret = __del_mtd_partitions(mtd);
	mutex_unlock(&master->master.partitions_lock);

	return ret;
}

functions.mtdchar_open:
static int mtdchar_open(struct inode *inode, struct file *file)
{
	int minor = iminor(inode);
	int devnum = minor >> 1;
	int ret = 0;
	struct mtd_info *mtd;
	struct mtd_file_info *mfi;

	pr_debug("MTD_open\n");

	/* You can't open the RO devices RW */
	if ((file->f_mode & FMODE_WRITE) && (minor & 1))
		return -EACCES;

	mtd = get_mtd_device(NULL, devnum);

	if (IS_ERR(mtd))
		return PTR_ERR(mtd);

	if (mtd->type == MTD_ABSENT) {
		ret = -ENODEV;
		goto out1;
	}

	/* You can't open it RW if it's not a writeable device */
	if ((file->f_mode & FMODE_WRITE) && !(mtd->flags & MTD_WRITEABLE)) {
		ret = -EACCES;
		goto out1;
	}

	mfi = kzalloc_obj(*mfi);
	if (!mfi) {
		ret = -ENOMEM;
		goto out1;
	}
	mfi->mtd = mtd;
	file->private_data = mfi;
	return 0;

out1:
	put_mtd_device(mtd);
	return ret;
}

functions.mtdchar_close:
static int mtdchar_close(struct inode *inode, struct file *file)
{
	struct mtd_file_info *mfi = file->private_data;
	struct mtd_info *mtd = mfi->mtd;

	pr_debug("MTD_close\n");

	/* Only sync if opened RW */
	if ((file->f_mode & FMODE_WRITE))
		mtd_sync(mtd);

	put_mtd_device(mtd);
	file->private_data = NULL;
	kfree(mfi);

	return 0;
}

functions.nand_get_device:
int nand_get_device(struct nand_chip *chip)
{
	/* Wait until the device is resumed. */
	while (1) {
		mutex_lock(&chip->lock);
		if (chip->disconnected) {
			mutex_unlock(&chip->lock);
			return -ENODEV;
		}
		if (!chip->suspended) {
			mutex_lock(&chip->controller->lock);
			return 0;
		}
		mutex_unlock(&chip->lock);

		wait_event(chip->resume_wq, !READ_ONCE(chip->suspended) ||
			   READ_ONCE(chip->disconnected));
	}
}

functions.nand_release_device:
void nand_release_device(struct nand_chip *chip)
{
	/* Release the controller and the chip */
	mutex_unlock(&chip->controller->lock);
	mutex_unlock(&chip->lock);
}

functions.nand_disconnect:
void nand_disconnect(struct nand_chip *chip)
{
	mutex_lock(&chip->lock);
	mutex_lock(&chip->controller->lock);
	WRITE_ONCE(chip->disconnected, true);
	mutex_unlock(&chip->controller->lock);
	mutex_unlock(&chip->lock);
	wake_up_all(&chip->resume_wq);
}

functions.nand_sync:
static void nand_sync(struct mtd_info *mtd)
{
	struct nand_chip *chip = mtd_to_nand(mtd);

	pr_debug("%s: called\n", __func__);

	/* Grab the lock and see if the device is available */
	if (nand_get_device(chip))
		return;
	/* Release it and go back */
	nand_release_device(chip);
}

functions.nand_suspend:
static int nand_suspend(struct mtd_info *mtd)
{
	struct nand_chip *chip = mtd_to_nand(mtd);
	int ret = 0;

	mutex_lock(&chip->lock);
	if (chip->disconnected) {
		mutex_unlock(&chip->lock);
		return 0;
	}
	if (chip->ops.suspend)
		ret = chip->ops.suspend(chip);
	if (!ret)
		WRITE_ONCE(chip->suspended, true);
	mutex_unlock(&chip->lock);

	return ret;
}

functions.nand_resume:
static void nand_resume(struct mtd_info *mtd)
{
	struct nand_chip *chip = mtd_to_nand(mtd);

	scoped_guard(mutex, &chip->lock) {
		if (chip->disconnected)
			return;
		if (chip->suspended) {
			if (chip->ops.resume)
				chip->ops.resume(chip);
			WRITE_ONCE(chip->suspended, false);
		} else {
			pr_err("%s called for a chip which is not in suspended state\n",
				__func__);
		}
	}

	wake_up_all(&chip->resume_wq);
}

functions.nand_controller_release:
static void nand_controller_release(struct kref *ref)
{
	struct nand_controller *controller;

	controller = container_of(ref, struct nand_controller, refcnt);
	controller->release(controller);
}

functions.nand_controller_put:
static void nand_controller_put(void *data)
{
	struct nand_controller *controller = data;

	kref_put(&controller->refcnt, nand_controller_release);
}

functions.devm_nand_controller_init:
int devm_nand_controller_init(struct device *dev, struct nand_controller *controller,
			      void (*release)(struct nand_controller *controller))
{
	nand_controller_init(controller);
	kref_init(&controller->refcnt);
	controller->release = release;

	return devm_add_action_or_reset(dev, nand_controller_put, controller);
}

functions.nand_mtd_get_device:
static int nand_mtd_get_device(struct mtd_info *mtd)
{
	struct nand_chip *chip = mtd_to_nand(mtd_get_master(mtd));

	guard(mutex)(&chip->lock);
	return chip->disconnected ? -ENODEV : 0;
}

functions.nand_mtd_release:
static void nand_mtd_release(struct mtd_info *mtd)
{
	struct nand_chip *chip = mtd_to_nand(mtd);
	struct nand_controller *controller = chip->controller;
	struct device *parent = mtd->dev.parent;
	struct device_node *np = nand_get_flash_node(chip);
	const char *name = mtd->name;

	if (!controller->release)
		controller = NULL;
	nand_cleanup(chip);
	of_node_put(np);
	kfree(name);
	if (chip->release)
		chip->release(chip);
	if (controller)
		nand_controller_put(controller);
	put_device(parent);
}

functions.nand_set_release:
int nand_set_release(struct nand_chip *chip,
		     void (*release)(struct nand_chip *chip))
{
	struct mtd_info *mtd = nand_to_mtd(chip);
	const char *name = mtd->name;
	char *copy;

	if (!name)
		name = dev_name(mtd->dev.parent);
	copy = kstrdup(name, GFP_KERNEL);
	if (!copy)
		return -ENOMEM;

	mtd->name = copy;
	mtd->_get_device = nand_mtd_get_device;
	get_device(mtd->dev.parent);
	of_node_get(nand_get_flash_node(chip));
	if (chip->controller->release)
		kref_get(&chip->controller->refcnt);
	chip->release = release;
	mtd_set_release(mtd, nand_mtd_release);

	return 0;
}

